'use strict';
const $=s=>document.querySelector(s),canvas=$('#map'),ctx=canvas.getContext('2d');let data=FpsLevel.load(localStorage),level=0,tool=0,painting=false,lastCell='',history=[],moving=null;
const colors=['#141e28','#895a35','#236ea6','#a27038','#286e60'];
for(let n=0;n<7;n++){const o=document.createElement('option');o.value=n;o.textContent='Étage '+(n+1);$('#floor').append(o);}
function message(text,error=false){$('#status').textContent=text;$('#status').style.color=error?'#ff9999':'#9fffd0';}
function checkpoint(){history.push(JSON.stringify(data));if(history.length>50)history.shift();}
function draw(){const map=data.maps[level];canvas.width=map[0].length*40;canvas.height=map.length*40;ctx.font='bold 11px monospace';ctx.textAlign='center';for(let z=0;z<map.length;z++)for(let x=0;x<map[0].length;x++){ctx.fillStyle=colors[map[z][x]];ctx.fillRect(x*40,z*40,40,40);ctx.strokeStyle='#34424e';ctx.strokeRect(x*40+.5,z*40+.5,39,39);}for(const p of FpsLevel.protectedCells(level,data)){ctx.fillStyle="rgba(255,227,111,.13)";ctx.fillRect(p.x*40,p.z*40,40,40);}for(const p of FpsLevel.points(level,data)){ctx.strokeStyle='#ffe36f';ctx.lineWidth=3;ctx.strokeRect(p.x*40+3,p.z*40+3,34,34);ctx.fillStyle='#ffe36f';ctx.fillText(p.label,p.x*40+20,p.z*40+17);ctx.fillText(FpsLevel.surface(p)==='ceiling'?'PLAFOND':'MUR',p.x*40+20,p.z*40+30);ctx.lineWidth=1;}}
function paint(e){const map=data.maps[level],r=canvas.getBoundingClientRect(),x=Math.floor((e.clientX-r.left)*map[0].length/r.width),z=Math.floor((e.clientY-r.top)*map.length/r.height),key=x+','+z;if(key===lastCell)return;lastCell=key;if(x<=0||x>=map[0].length-1||z<=0||z>=map.length-1)return;if(moving){moveAccess(x,z);return;}if(FpsLevel.protectedCells(level,data).some(p=>p.x===x&&p.z===z)){message('Les accès sont protégés.',true);return;}data.maps[level][z][x]=tool;draw();}
canvas.onpointerdown=e=>{e.preventDefault();canvas.focus();checkpoint();painting=true;lastCell='';canvas.setPointerCapture(e.pointerId);paint(e);};canvas.onpointermove=e=>{if(painting)paint(e);};canvas.onpointerup=canvas.onpointercancel=()=>painting=false;
document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>{tool=Number(b.dataset.tool);document.querySelectorAll('[data-tool]').forEach(t=>t.setAttribute('aria-pressed',String(t===b)));});$('#floor').onchange=()=>{level=Number($('#floor').value);moving=null;controls();draw();};
function controls(){const selected=$('#access').value||'0';const map=data.maps[level];$("#width").value=map[0].length;$("#height").value=map.length;$("#access").replaceChildren(...FpsLevel.points(level,data).map((p,i)=>{const o=document.createElement("option");o.value=i;o.textContent=p.label+' · '+(FpsLevel.surface(p)==='ceiling'?'plafond':'mur');return o;}));$("#access").value=String(Math.min(Number(selected),$("#access").options.length-1));accessType();}
function undo(){if(history.length){data=JSON.parse(history.pop());moving=null;controls();draw();message('Modification annulée.');}}$('#undo').onclick=undo;document.addEventListener('keydown',e=>{if(e.ctrlKey&&e.key.toLowerCase()==='z'&&!(e.target instanceof HTMLInputElement)){e.preventDefault();undo();}});
$('#reset-floor').onclick=()=>{checkpoint();const map=data.maps[level];data.maps[level]=map.map((row,z)=>row.map((v,x)=>x===0||z===0||x===row.length-1||z===map.length-1?1:0));draw();message('Étage réinitialisé. Appliquez pour modifier le jeu.');};
function apply(){try{data=FpsLevel.validate(data);localStorage.setItem(FpsLevel.KEY,JSON.stringify(data));message('Niveau appliqué. Rechargez le jeu pour le charger.');return true;}catch(e){message(e.message,true);return false;}}
$('#apply').onclick=apply;$('#test').onclick=()=>{if(apply())window.open('./?fps-test=true&fps-floor='+level,'_blank','noopener');};
$('#export').onclick=()=>{try{const value=FpsLevel.validate(data),url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='minitman-fps-level.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch(e){message(e.message,true);}};
$('#import').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;const imported=FpsLevel.validate(JSON.parse(await file.text()));checkpoint();data=imported;controls();draw();message('Niveau importé. Cliquez sur Appliquer au jeu.');}catch(e){message(e.message,true);}e.target.value='';};controls();draw();

$('#move-access').onclick=()=>{moving=FpsLevel.points(level,data)[Number($('#access').value)];message('Cliquez dans la grille pour déplacer : '+moving.label);};
function moveAccess(x,z){const copy=JSON.parse(JSON.stringify(data)),target=moving.id==='stairs'?copy.structure.stairs[moving.index]:copy.structure[moving.id];Object.assign(target,{x,z});const levels=moving.id==='stairs'?[moving.index,moving.index+1]:[level];for(const n of levels){const map=copy.maps[n];if(x<2||z<2||x>=map[0].length-1||z>=map.length-1){message('Cet accès doit tenir sur les deux étages reliés.',true);return;}for(const p of FpsLevel.protectedCells(n,copy))map[p.z][p.x]=0;}data=copy;moving=null;painting=false;controls();draw();message('Accès déplacé. Appliquez pour enregistrer.');}
$('#resize').onclick=()=>{const w=Number($('#width').value),h=Number($('#height').value);if(!Number.isInteger(w)||!Number.isInteger(h)||w<10||w>64||h<10||h>48){message('Taille : largeur 10–64 et profondeur 10–48.',true);return;}if(FpsLevel.points(level,data).some(p=>p.x>=w-1||p.z>=h-1)){message('Déplacez les accès dans la nouvelle taille avant de réduire.',true);return;}checkpoint();const old=data.maps[level];data.maps[level]=Array.from({length:h},(_,z)=>Array.from({length:w},(_,x)=>x===0||z===0||x===w-1||z===h-1?1:x===old[0].length-1||z===old.length-1?0:old[z]?.[x]??0));controls();draw();message('Étage redimensionné. Ctrl+Z pour annuler.');};

function accessType(){const point=FpsLevel.points(level,data)[Number($('#access').value)||0];$('#surface').value=FpsLevel.surface(point);}
$('#access').onchange=accessType;
$('#surface').onchange=()=>{checkpoint();const point=FpsLevel.points(level,data)[Number($('#access').value)||0],target=point.id==='stairs'?data.structure.stairs[point.index]:data.structure[point.id];target.surface=$('#surface').value;controls();draw();message('Type d’accès modifié.');};
